const raw = $input.first().json || {};
const body = (raw.body && typeof raw.body === 'object') ? raw.body : raw;
const query = (raw.query && typeof raw.query === 'object') ? raw.query : {};
const periodRaw = String(body.period || query.period || '7d').trim().toLowerCase();
const daysMap = { '24h': 1, '1d': 1, '7d': 7, '30d': 30, 'all': 36500 };
const days = daysMap[periodRaw] || 7;
const period = daysMap[periodRaw] ? periodRaw : '7d';
const limitNum = Number(body.limit || query.limit || 5);
const limit = Number.isFinite(limitNum) ? Math.min(Math.max(Math.round(limitNum), 1), 20) : 5;
return [{ json: { period, days, limit } }];

const row = $input.first().json || {};
const filters = $('Normalizar Filtros').first().json || { period: '7d', limit: 5 };
return [{
  json: {
    ok: true,
    period: filters.period,
    totalScrobbles: Number(row.total_scrobbles || 0),
    uniqueTracks: Number(row.unique_tracks || 0),
    topTracks: Array.isArray(row.top_tracks) ? row.top_tracks : [],
    topArtists: Array.isArray(row.top_artists) ? row.top_artists : [],
    recent: Array.isArray(row.recent) ? row.recent : []
  }
}];
